mapper.select:
SELECT * FROM (
    SELECT  FROM FOOD_BUSINESS B

        (B.BIZ_NAME LIKE '%' || #{q} || '%' OR B.ADDRESS LIKE '%' || #{q} || '%' OR B.OWNER_NAME LIKE '%' || #{q} || '%')
        AND B.BIZ_TYPE = #{type}

     ORDER BY CASE WHEN B.STATUS = 'OPEN' THEN 0 ELSE 1 END, B.BIZ_NAME
) WHERE ROWNUM <= #{limit}
